"""Minimum String Length After Removing Substrings — stack.

Removing "AB" or "CD" can expose a new pair, which the stack handles naturally.

Time: O(n)   Space: O(n)
"""


class Solution:
    def minLength(self, s: str) -> int:
        stack = []
        for ch in s:
            if stack and (stack[-1] + ch) in ("AB", "CD"):
                stack.pop()
            else:
                stack.append(ch)
        return len(stack)
